#   createdb t && psql -d t -f supabase/tests/supabase_stub.sql -f supabase/migrations/0001_initial.sql -f supabase/migrations/0002_security.sql -f supabase/migrations/0003_scoring_and_video.sql -f supabase/migrations/0004_notifications.sql -f supabase/migrations/0005_pairing_options.sql -f supabase/migrations/0006_past_results.sql -f supabase/migrations/0007_entry_controls_and_moderation.sql -f supabase/migrations/0008_account_deletion.sql -f supabase/migrations/0010_admin_roles.sql
#   PGARGS='-h localhost -U postgres -d t' python3 supabase/tests/security_test.py
PG = os.environ.get('PGARGS', '-d t').split()
U = {n: str(uuid.uuid5(uuid.NAMESPACE_DNS, n)) for n in ['org','org2','judge','judge2','coachA','coachB','compA','evil','admin','newbie']}
LIMITED = ['tournaments', 'registrations', 'teams', 'cases', 'bulletins', 'messages', 'reports']
FRESH = True  # most tests are not about rate limits: age every earlier row past the limit windows first
def psql(sql, who=None, superuser=False):
    age = ('set local session_replication_role = replica; ' + ' '.join(f"update {t} set inserted_at = now() - interval '2 days';" for t in LIMITED)
           + ' set local session_replication_role = origin; ') if FRESH and not superuser else ''
    pre = age + ('' if superuser else (f"set local role authenticated; set local request.jwt.claim.sub = '{U[who]}';" if who else "set local role anon;"))
    r = subprocess.run(['psql', *PG,'-qtA','-v','ON_ERROR_STOP=1','-c', f"begin; {pre} {sql}; commit;"], capture_output=True, text=True)
    return r.returncode == 0, (r.stdout.strip() or r.stderr.strip().split('\n')[0])
fails = 0
def ok(name, sql, who=None, expect=None):
    global fails
    good, out = psql(sql, who)
    passed = good and (expect is None or out == str(expect))
    print(('PASS ' if passed else 'FAIL ') + 'allowed: ' + name + ('' if passed else f'  -> {out}'))
    fails += not passed
def blocked(name, sql, who=None, rows_if_ok=None):
    """Attack must error, or (for silent RLS filters) affect/see `rows_if_ok` rows."""
    global fails
    good, out = psql(sql, who)
    passed = (not good) or (rows_if_ok is not None and out == str(rows_if_ok))
    print(('PASS ' if passed else 'FAIL ') + 'blocked: ' + name + ('' if passed else f'  -> {out}') + (f'   [{out[:90]}]' if passed and not good else ''))
    fails += not passed

